"use client";
import { useState } from "react";
import { Check } from "lucide-react";
import { Button, Card, Badge, Switch, Input, Dialog } from "@/components/ui/primitives";
import { Heading, type SectionProps } from "./shared";
export function PricingSection({ content, variant, className = "" }: SectionProps) {
  const [annual, setAnnual] = useState(false);
  const [seats, setSeats] = useState(5);
  const [selected, setSelected] = useState<string | null>(null);
  const plans =
    variant === "single"
      ? content.items.slice(0, 1)
      : variant === "toggle"
        ? content.items.slice(0, 2)
        : content.items;
  return (
    <section className={"section pricing pricing-" + variant + " " + className}>
      <Heading content={content}>
        {["toggle", "three-tier"].includes(variant) && (
          <Switch label="Annual billing · save 20%" checked={annual} onCheckedChange={setAnnual} />
        )}
      </Heading>
      {variant === "usage" && (
        <label className="usage-control">
          Team members: {seats}
          <Input
            type="range"
            min={1}
            max={100}
            value={seats}
            onChange={(e) => setSeats(Number(e.target.value))}
          />
        </label>
      )}
      <div className="pricing-grid">
        {plans.map((p, i) => (
          <Card key={i} className={i === 1 ? "featured-plan" : ""}>
            {i === 1 && <Badge>Most popular</Badge>}
            <h3>{p.title}</h3>
            <p>{p.description}</p>
            <div className="price">
              {variant === "enterprise" && i === 2
                ? "Let's talk"
                : "$" +
                  Math.round(
                    [19, 49, 99][i] * (annual ? 0.8 : 1) * (variant === "usage" ? seats : 1),
                  )}
              <small>{variant === "enterprise" && i === 2 ? "Custom plans" : "/ month"}</small>
            </div>
            <ul>
              {[
                "Core features included",
                "Flexible configuration",
                "Helpful documentation",
                ...(i > 0 ? ["Team collaboration", "Priority support"] : []),
              ].map((f) => (
                <li key={f}>
                  <Check size={16} />
                  {f}
                </li>
              ))}
            </ul>
            <Button variant={i === 1 ? "default" : "outline"} onClick={() => setSelected(p.title)}>
              Choose {p.title}
            </Button>
          </Card>
        ))}
      </div>
      {variant === "comparison" && (
        <table className="comparison-table">
          <caption>Plan comparison</caption>
          <thead>
            <tr>
              <th>Feature</th>
              {plans.map((p) => (
                <th key={p.title}>{p.title}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {["Projects", "Members", "Support"].map((r, i) => (
              <tr key={r}>
                <th>{r}</th>
                <td>{["3", "1", "Community"][i]}</td>
                <td>{["Unlimited", "10", "Priority"][i]}</td>
                <td>{["Unlimited", "Unlimited", "Dedicated"][i]}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
      <Dialog
        title={(selected || "Plan") + " selected"}
        description="Demo plan selection. Connect your own checkout to accept payments."
        open={!!selected}
        onOpenChange={(o) => {
          if (!o) setSelected(null);
        }}
      >
        <p>
          Your selected plan is <strong>{selected}</strong>, billed{" "}
          {annual ? "annually" : "monthly"}.
        </p>
        <Button onClick={() => setSelected(null)}>Continue exploring</Button>
      </Dialog>
    </section>
  );
}

"use client";
import { useState, type ReactNode } from "react";
import { Layers, Check, BarChart3, Zap, Command } from "lucide-react";
import { Button, Input, Alert, Card, Badge } from "@/components/ui/primitives";
import type { SectionContent } from "@/registry/schema";
export type SectionProps = { content: SectionContent; variant: string; className?: string };
export function Heading({ content, children }: { content: SectionContent; children?: ReactNode }) {
  return (
    <header className="section-heading">
      <div>
        <span className="eyebrow">{content.eyebrow}</span>
        <h2>{content.title}</h2>
        {content.description && <p>{content.description}</p>}
      </div>
      {children}
    </header>
  );
}
export function Action({
  content,
  secondary = false,
}: {
  content: SectionContent;
  secondary?: boolean;
}) {
  return (
    <Button asChild variant={secondary ? "outline" : "default"}>
      <a href={content.href || "#content-contact"}>{content.action || "Explore the details"}</a>
    </Button>
  );
}
export function Signup({ label = "Join the list" }: { label?: string }) {
  const [done, setDone] = useState(false);
  return done ? (
    <Alert title="You're on the demo list." variant="success">
      This sample saves no personal data and sends no email.
    </Alert>
  ) : (
    <form
      className="signup-form"
      onSubmit={(e) => {
        e.preventDefault();
        setDone(true);
      }}
    >
      <Input type="email" aria-label="Email address" placeholder="you@example.com" required />
      <Button type="submit">{label}</Button>
    </form>
  );
}
export function SampleVisual({ variant = "dashboard" }: { variant?: string }) {
  return (
    <div className={"sample-visual sample-" + variant} aria-label="Sample product interface">
      <div className="sample-top">
        <span>
          <Layers size={16} /> Workspace
        </span>
        <Badge>Live preview</Badge>
      </div>
      <div className="sample-body">
        <aside>
          <Command size={18} />
          <BarChart3 size={18} />
          <Layers size={18} />
          <Zap size={18} />
        </aside>
        <div>
          <div className="spread">
            <div>
              <span className="muted">This week’s progress</span>
              <h3>A little better, every day.</h3>
            </div>
            <Badge>+18.6%</Badge>
          </div>
          <div className="mini-metrics">
            <Card>
              <small>Completed</small>
              <strong>248</strong>
            </Card>
            <Card>
              <small>In progress</small>
              <strong>32</strong>
            </Card>
          </div>
          <div className="mini-bars" aria-label="Weekly activity chart">
            {[38, 52, 45, 72, 58, 84, 68, 92, 78, 100, 86, 96].map((h, i) => (
              <span key={i} style={{ height: h + "%" }} />
            ))}
          </div>
          <div className="sample-task">
            <Check size={15} /> Launch checklist completed <span className="muted">Just now</span>
          </div>
        </div>
      </div>
    </div>
  );
}
export function ItemCards({
  content,
  className = "",
}: {
  content: SectionContent;
  className?: string;
}) {
  return (
    <div className={"item-grid " + className}>
      {content.items.map((item, i) => (
        <Card key={i}>
          <span className="item-number">{String(i + 1).padStart(2, "0")}</span>
          <h3>{item.title}</h3>
          <p>{item.description}</p>
        </Card>
      ))}
    </div>
  );
}

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Slot } from "radix-ui";

const buttonVariants = cva("ui-button", {
  variants: {
    variant: {
      default: "button-primary",
      secondary: "button-secondary",
      outline: "button-outline",
      ghost: "button-ghost",
      destructive: "button-destructive",
      link: "ui-link",
    },
    size: { default: "", sm: "button-sm", icon: "button-icon" },
  },
  defaultVariants: { variant: "default", size: "default" },
});

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean;
  }) {
  const Comp = asChild ? Slot.Root : "button";

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      type={asChild ? undefined : "button"}
      {...props}
    />
  );
}

export { Button, buttonVariants };

"use client";
import * as React from "react";
import type { SectionContent } from "@/registry/schema";
import {
  Dialog as RDialog,
  Popover as RPopover,
  Tooltip as RTooltip,
  Tabs as RTabs,
  Accordion as RAccordion,
  DropdownMenu as RMenu,
  Switch as RSwitch,
} from "radix-ui";
import { X, Check, ChevronDown, Search, LoaderCircle } from "lucide-react";
import { cn } from "@/lib/utils";
import { useThemeVariables } from "./theme-scope";
import { Button } from "./button";
export { Button } from "./button";
export function Link({ className, ...props }: React.ComponentProps<"a">) {
  return <a className={cn("ui-link", className)} {...props} />;
}
export function Input({ className, ...props }: React.ComponentProps<"input">) {
  return <input className={cn("ui-input", className)} {...props} />;
}
export function Textarea({ className, ...props }: React.ComponentProps<"textarea">) {
  return <textarea className={cn("ui-input", className)} {...props} />;
}
export function Label(props: React.ComponentProps<"label">) {
  return <label className="ui-label" {...props} />;
}
export function Select({
  label,
  options,
  className,
  id: providedId,
  ...props
}: React.ComponentProps<"select"> & {
  label: string;
  options: { value: string; label: string }[];
}) {
  const generatedId = React.useId();
  const id = providedId || generatedId;
  return (
    <div className={cn("ui-field", className)}>
      <label htmlFor={id}>{label}</label>
      <select id={id} className="ui-input" {...props}>
        {options.map((o) => (
          <option key={o.value} value={o.value}>
            {o.label}
          </option>
        ))}
      </select>
    </div>
  );
}
export function Checkbox({ label, ...props }: React.ComponentProps<"input"> & { label: string }) {
  return (
    <label className="check-label">
      <input type="checkbox" {...props} />
      <span>{label}</span>
    </label>
  );
}
export function Radio({ label, ...props }: React.ComponentProps<"input"> & { label: string }) {
  return (
    <label className="check-label">
      <input type="radio" {...props} />
      <span>{label}</span>
    </label>
  );
}
export function Switch({
  label,
  id: providedId,
  ...props
}: React.ComponentProps<typeof RSwitch.Root> & { label: string }) {
  const generatedId = React.useId();
  const id = providedId || generatedId;
  return (
    <div className="check-label">
      <RSwitch.Root id={id} className="ui-switch" {...props}>
        <RSwitch.Thumb className="switch-thumb" />
      </RSwitch.Root>
      <label htmlFor={id}>{label}</label>
    </div>
  );
}
export function Badge({ className, ...props }: React.ComponentProps<"span">) {
  return <span className={cn("ui-badge", className)} {...props} />;
}
export function Avatar({ name, className }: { name: string; className?: string }) {
  return (
    <span role="img" aria-label={name} className={cn("ui-avatar", className)}>
      {name
        .split(" ")
        .map((s) => s[0])
        .slice(0, 2)
        .join("")}
    </span>
  );
}
export function Card({
  variant = "plain",
  className,
  ...props
}: React.ComponentProps<"article"> & { variant?: string }) {
  return <article className={cn("ui-card", "card-" + variant, className)} {...props} />;
}
export function CardSection({
  content,
  variant,
  className,
}: {
  content: SectionContent;
  variant: string;
  className?: string;
}) {
  return (
    <Card variant={variant} className={className}>
      <span className="eyebrow">{content.eyebrow}</span>
      <h3>{content.title}</h3>
      <p>{content.description}</p>
    </Card>
  );
}
export function Separator() {
  return <hr className="ui-separator" />;
}
export function Tooltip({ label, children }: { label: string; children: React.ReactNode }) {
  const variables = useThemeVariables();
  return (
    <RTooltip.Provider delayDuration={200}>
      <RTooltip.Root>
        <RTooltip.Trigger asChild>{children}</RTooltip.Trigger>
        <RTooltip.Portal>
          <RTooltip.Content
            className="ui-tooltip"
            style={variables}
            sideOffset={8}
            collisionPadding={12}
          >
            {label}
            <RTooltip.Arrow />
          </RTooltip.Content>
        </RTooltip.Portal>
      </RTooltip.Root>
    </RTooltip.Provider>
  );
}
export function Popover({
  trigger,
  children,
}: {
  trigger: React.ReactNode;
  children: React.ReactNode;
}) {
  const variables = useThemeVariables();
  return (
    <RPopover.Root>
      <RPopover.Trigger asChild>{trigger}</RPopover.Trigger>
      <RPopover.Portal>
        <RPopover.Content
          className="ui-popover"
          style={variables}
          sideOffset={8}
          collisionPadding={12}
        >
          {children}
          <RPopover.Close asChild>
            <Button variant="ghost" size="sm">
              Close
            </Button>
          </RPopover.Close>
        </RPopover.Content>
      </RPopover.Portal>
    </RPopover.Root>
  );
}
export function Dialog({
  trigger,
  title,
  description,
  children,
  open,
  onOpenChange,
  drawer = false,
}: {
  trigger?: React.ReactNode;
  title: string;
  description?: string;
  children: React.ReactNode;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  drawer?: boolean;
}) {
  const variables = useThemeVariables();
  return (
    <RDialog.Root open={open} onOpenChange={onOpenChange}>
      {trigger && <RDialog.Trigger asChild>{trigger}</RDialog.Trigger>}
      <RDialog.Portal>
        <RDialog.Overlay className="dialog-overlay" />
        <RDialog.Content style={variables} className={cn("ui-dialog", drawer && "ui-drawer")}>
          <RDialog.Title>{title}</RDialog.Title>
          <RDialog.Description>{description || "Complete the details below."}</RDialog.Description>
          {children}
          <RDialog.Close asChild>
            <Button className="dialog-close" variant="ghost" size="icon" aria-label="Close dialog">
              <X size={18} />
            </Button>
          </RDialog.Close>
        </RDialog.Content>
      </RDialog.Portal>
    </RDialog.Root>
  );
}
export function Drawer(props: React.ComponentProps<typeof Dialog>) {
  return <Dialog {...props} drawer />;
}
export function Accordion({
  items,
  defaultValue,
}: {
  items: { title: string; content: React.ReactNode }[];
  defaultValue?: string;
}) {
  return (
    <RAccordion.Root type="single" collapsible defaultValue={defaultValue} className="ui-accordion">
      {items.map((item, i) => (
        <RAccordion.Item value={String(i)} key={i}>
          <RAccordion.Header>
            <RAccordion.Trigger>
              {item.title}
              <ChevronDown size={17} />
            </RAccordion.Trigger>
          </RAccordion.Header>
          <RAccordion.Content>
            <div>{item.content}</div>
          </RAccordion.Content>
        </RAccordion.Item>
      ))}
    </RAccordion.Root>
  );
}
export function Tabs({
  items,
  defaultValue,
  onValueChange,
}: {
  items: { id: string; label: string; content: React.ReactNode }[];
  defaultValue?: string;
  onValueChange?: (v: string) => void;
}) {
  return (
    <RTabs.Root defaultValue={defaultValue || items[0]?.id} onValueChange={onValueChange}>
      <RTabs.List className="ui-tabs" aria-label="Content views">
        {items.map((i) => (
          <RTabs.Trigger key={i.id} value={i.id}>
            {i.label}
          </RTabs.Trigger>
        ))}
      </RTabs.List>
      {items.map((i) => (
        <RTabs.Content className="tab-panel" key={i.id} value={i.id}>
          {i.content}
        </RTabs.Content>
      ))}
    </RTabs.Root>
  );
}
export function Breadcrumbs({ items }: { items: { label: string; href?: string }[] }) {
  return (
    <nav aria-label="Breadcrumb">
      <ol className="breadcrumbs">
        {items.map((i, n) => (
          <li key={n}>
            {i.href ? (
              <a href={i.href}>{i.label}</a>
            ) : (
              <span aria-current={n === items.length - 1 ? "page" : undefined}>{i.label}</span>
            )}
          </li>
        ))}
      </ol>
    </nav>
  );
}
export function Pagination({
  page,
  pages,
  onChange,
}: {
  page: number;
  pages: number;
  onChange: (p: number) => void;
}) {
  return (
    <nav className="pagination" aria-label="Pagination">
      <Button variant="outline" size="sm" disabled={page <= 1} onClick={() => onChange(page - 1)}>
        Previous
      </Button>
      <span>
        Page {page} of {Math.max(1, pages)}
      </span>
      <Button
        variant="outline"
        size="sm"
        disabled={page >= pages}
        onClick={() => onChange(page + 1)}
      >
        Next
      </Button>
    </nav>
  );
}
export function Skeleton({ className }: { className?: string }) {
  return <span aria-hidden="true" className={cn("ui-skeleton", className)} />;
}
export function Progress({ value, label }: { value: number; label: string }) {
  return (
    <div className="progress-wrap">
      <div className="spread">
        <span>{label}</span>
        <span>{Math.round(value)}%</span>
      </div>
      <progress max={100} value={Math.min(100, Math.max(0, value))} aria-label={label} />
    </div>
  );
}
export function Alert({
  title,
  children,
  variant = "info",
}: {
  title: string;
  children?: React.ReactNode;
  variant?: "info" | "error" | "success";
}) {
  return (
    <div role={variant === "error" ? "alert" : "status"} className={"ui-alert alert-" + variant}>
      <strong>{title}</strong>
      {children && <p>{children}</p>}
    </div>
  );
}
export function Toast({ message, onDismiss }: { message: string; onDismiss: () => void }) {
  React.useEffect(() => {
    const t = setTimeout(onDismiss, 5000);
    return () => clearTimeout(t);
  }, [message, onDismiss]);
  return (
    <div role="status" className="ui-toast">
      <Check size={18} />
      {message}
      <Button variant="ghost" size="icon" aria-label="Dismiss notification" onClick={onDismiss}>
        <X size={16} />
      </Button>
    </div>
  );
}
export function DropdownMenu({
  label,
  items,
}: {
  label: string;
  items: { label: string; onSelect: () => void; disabled?: boolean }[];
}) {
  const variables = useThemeVariables();
  return (
    <RMenu.Root>
      <RMenu.Trigger asChild>
        <Button variant="outline">
          {label}
          <ChevronDown size={15} />
        </Button>
      </RMenu.Trigger>
      <RMenu.Portal>
        <RMenu.Content className="ui-menu" style={variables} sideOffset={6} collisionPadding={12}>
          {items.map((i, n) => (
            <RMenu.Item key={n} disabled={i.disabled} onSelect={i.onSelect}>
              {i.label}
            </RMenu.Item>
          ))}
        </RMenu.Content>
      </RMenu.Portal>
    </RMenu.Root>
  );
}
export function CommandMenu({ items }: { items: { label: string; href: string }[] }) {
  const [q, setQ] = React.useState("");
  return (
    <Dialog
      title="Go to…"
      trigger={
        <Button variant="outline">
          <Search size={16} />
          Quick navigation
        </Button>
      }
    >
      <Input
        aria-label="Search commands"
        autoFocus
        value={q}
        onChange={(e) => setQ(e.target.value)}
      />
      <nav className="command-results" aria-label="Command results">
        {items
          .filter((i) => i.label.toLowerCase().includes(q.toLowerCase()))
          .map((i) => (
            <a key={i.href} href={i.href}>
              {i.label}
            </a>
          ))}
        {!items.some((i) => i.label.toLowerCase().includes(q.toLowerCase())) && (
          <p>No matching commands.</p>
        )}
      </nav>
    </Dialog>
  );
}
export function FormField({
  label,
  error,
  children,
}: {
  label: string;
  error?: string;
  children: React.ReactElement<{
    id?: string;
    "aria-describedby"?: string;
    "aria-invalid"?: boolean;
  }>;
}) {
  const generatedId = React.useId();
  const id = children.props.id || generatedId;
  const describedBy =
    [children.props["aria-describedby"], error ? id + "-error" : undefined]
      .filter(Boolean)
      .join(" ") || undefined;
  return (
    <div className="ui-field">
      <Label htmlFor={id}>{label}</Label>
      {React.cloneElement(children, {
        id,
        "aria-describedby": describedBy,
        "aria-invalid": error ? true : children.props["aria-invalid"],
      })}
      {error && (
        <span role="alert" className="field-error" id={id + "-error"}>
          {error}
        </span>
      )}
    </div>
  );
}
export function Loading({ label = "Loading…" }: { label?: string }) {
  return (
    <div role="status" className="loading-state">
      <LoaderCircle className="loading-spinner" size={22} />
      <span>{label}</span>
    </div>
  );
}
export function EmptyState({
  title = "No results",
  description = "Try a different search or clear your filters.",
  action,
}: {
  title?: string;
  description?: string;
  action?: React.ReactNode;
}) {
  return (
    <div className="empty-state">
      <Search size={28} />
      <h3>{title}</h3>
      <p>{description}</p>
      {action}
    </div>
  );
}

"use client";
import { createContext, useContext, type CSSProperties, type ReactNode } from "react";
const ThemeContext = createContext<CSSProperties>({});
export function ThemeScope({
  variables,
  children,
}: {
  variables: CSSProperties;
  children: ReactNode;
}) {
  return <ThemeContext.Provider value={variables}>{children}</ThemeContext.Provider>;
}
export function useThemeVariables() {
  return useContext(ThemeContext);
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export function cn(...values: ClassValue[]) {
  return twMerge(clsx(values));
}
export function title(id: string) {
  return id
    .split("-")
    .map((s) => s[0].toUpperCase() + s.slice(1))
    .join(" ");
}

.border-glow {
  position: relative;
  isolation: isolate;
  padding: 2px;
  border-radius: var(--radius);
  width: 100%;
  min-width: 0;
}
.effect-edge {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  overflow: hidden;
  z-index: -1;
  pointer-events: none;
  background: var(--border);
}
.effect-edge::before {
  content: "";
  position: absolute;
  inset: -150%;
  background: conic-gradient(
    from 0deg,
    transparent 45%,
    var(--primary),
    var(--chart-2),
    transparent 85%
  );
  opacity: var(--effect-strength);
  animation: effect-orbit var(--effect-duration) linear infinite;
}
.effect-edge::after {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: max(0px, calc(var(--radius) - 2px));
  background: var(--card);
}
.border-glow-content {
  padding: clamp(16px, 4cqi, 32px);
  color: var(--card-foreground);
}
.border-glow-content > * + * {
  margin-top: 16px;
}
.status-orb-wrap {
  display: inline-grid;
  place-items: center;
  max-width: 100%;
}
.status-orb {
  display: inline-grid;
  width: var(--orb-size);
  max-width: 100%;
  aspect-ratio: 1;
  border-radius: 50%;
  overflow: hidden;
  position: relative;
  isolation: isolate;
  background: var(--primary);
  box-shadow:
    inset 0 -6px 15px #00000030,
    0 0 28px color-mix(in srgb, var(--primary) 18%, transparent);
}
.status-orb > span {
  position: absolute;
  inset: -30%;
  border-radius: 42%;
  background: conic-gradient(var(--primary), var(--chart-2), var(--accent), var(--primary));
  animation: effect-orbit var(--effect-duration) linear infinite;
}
.status-orb::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(circle at 30% 22%, #ffffffaa, transparent 40%, #00000044);
}
.orb-listening > span {
  animation-direction: reverse;
  border-radius: 30%;
}
.orb-idle {
  opacity: 0.65;
}
.orb-complete {
  --primary: var(--success);
  --chart-2: var(--success);
}
.orb-error {
  --primary: var(--destructive);
  --chart-2: var(--destructive);
}
.metallic-button {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--foreground);
  color: var(--background);
  border: 1px solid var(--foreground);
  box-shadow:
    inset 0 1px 0 #ffffff70,
    inset 0 -2px 0 #00000030;
}
.metallic-button::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: -1;
  background: linear-gradient(115deg, transparent 20%, #ffffff35 45%, transparent 65%);
  transform: translateX(-100%);
}
.metallic-button:is(:hover, :focus-visible)::before {
  animation: effect-sheen 1.2s ease-out;
}
.border-glow[data-active="false"] .effect-edge::before,
.status-orb[data-active="false"] > span {
  animation-play-state: paused;
}
.metallic-button[data-active="false"]::before {
  animation: none;
}
@keyframes effect-orbit {
  to {
    transform: rotate(360deg);
  }
}
@keyframes effect-sheen {
  to {
    transform: translateX(100%);
  }
}
@media (prefers-reduced-motion: reduce) {
  .effect-edge::before,
  .status-orb > span,
  .metallic-button::before {
    animation: none !important;
  }
}

