  font-weight: var(--body-weight);
  min-height: var(--preview-min-height, 100dvh);
}
.factory-preview main {
  min-width: 0;
}
.factory-preview .section,
.factory-preview .hero,
.factory-preview .template-nav,
.factory-preview .template-footer {
  width: min(calc(100% - 96px), var(--content-width));
  margin-left: auto;
  margin-right: auto;
}
.factory-preview .section {
  padding-top: calc(76px * var(--density));
  padding-bottom: calc(76px * var(--density));
}
.section-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 40px;
}
.section-heading > div {
  max-width: 700px;
}
.section-heading p {
  margin-top: 18px;
  max-width: 600px;
}
.section-heading h2 {
  font-size: calc(clamp(1.75rem, 3cqi, 2.6rem) * var(--heading-scale));
}
.factory-preview[data-background="grid"] {
  background-image:
    linear-gradient(color-mix(in srgb, var(--border) 8%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in srgb, var(--border) 8%, transparent) 1px, transparent 1px);
  background-size: 48px 48px;
}
.factory-preview[data-background="gradient"] {
  background-image: var(--gradient-hero);
}
.factory-preview[data-surface="glass"] .ui-card {
  background: color-mix(in srgb, var(--card) 76%, transparent);
  backdrop-filter: blur(8px);
}
.factory-preview[data-surface="inset"] .ui-card {
  box-shadow:
    inset 3px 3px 9px #0000000b,
    4px 4px 16px #0000000c;
  background: var(--muted);
}
.factory-preview[data-button="pill"] .ui-button {
  border-radius: 99px;
}
.factory-preview[data-button="outline"] .button-primary {
  border-color: var(--primary);
  color: var(--primary);
  background: transparent;
}
.factory-preview[data-button="offset"] .ui-button {
  border: 2px solid var(--foreground);
  box-shadow: 3px 3px 0 var(--foreground);
  border-radius: 0;
}
.factory-preview[data-input="underline"] .ui-input {
  border-width: 0 0 1px;
  border-radius: 0;
  background: transparent;
}
.factory-preview[data-input="inset"] .ui-input {
  box-shadow: inset 2px 2px 6px #00000012;
  background: var(--muted);
}
.factory-preview[data-decoration="dots"] .hero {
  background-image: radial-gradient(
    color-mix(in srgb, var(--primary) 15%, transparent) 1px,
    transparent 1px
  );
  background-size: 20px 20px;
}
.factory-preview[data-decoration="lines"] .section-heading {
  border-top: 1px solid var(--border);
  padding-top: 25px;
}
.factory-preview[data-card="elevated"] .ui-card {
  box-shadow: 0 12px 30px #00000016;
}
.factory-preview[data-card="outline"] .ui-card {
  border: 2px solid var(--primary);
  background: transparent;
}
.factory-preview[data-card="accent"] .ui-card {
  background: var(--accent);
  border-left: 4px solid var(--primary);
}
.factory-preview[data-card="image"] .ui-card {
  background: var(--gradient-hero);
}
.factory-preview[data-card="horizontal"] .item-grid .ui-card {
  display: flex;
  gap: 20px;
  align-items: center;
}
.factory-preview[data-card="metric"] .ui-card h3 {
  font-size: 1.5rem;
}
.factory-preview[data-card="interactive"] .ui-card:hover {
  box-shadow: 0 8px 24px #00000018;
  transform: translateY(-2px);
}
.template-nav {
  display: flex;
  align-items: center;
  gap: 28px;
  padding: 24px 0;
  position: relative;
  z-index: 10;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -0.04em;
  white-space: nowrap;
}
.nav-links {
  display: flex;
  gap: 28px;
  align-items: center;
  margin-left: auto;
  font-size: 0.875rem;
}
.nav-links > a {
  color: var(--muted-foreground);
}
.nav-links > a:hover {
  color: var(--foreground);
}
.nav-mobile {
  display: none;
}
.nav-floating {
  border: 1px solid var(--border);
  border-radius: 50px;
  padding: 12px 20px !important;
  margin-top: 22px;
  background: var(--card);
  box-shadow: 0 8px 24px #00000008;
}
.nav-centered .brand {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
}
.nav-centered .nav-links {
  margin-left: 0;
}
.nav-centered .nav-action {
  margin-left: auto;
}
.nav-split .brand {
  font-family: var(--font-heading);
  font-size: 1.5rem;
}
.nav-split .nav-links {
  margin: auto;
}
.nav-editorial {
  border-top: 4px solid var(--foreground);
  border-bottom: 1px solid var(--border);
  margin-top: 16px;
  padding: 18px 0;
}
.nav-editorial .brand {
  font-family: Georgia, serif;
  font-size: 1.7rem;
}
.nav-transparent {
  border-bottom: 1px solid var(--border);
}
.nav-compact {
  padding: 15px 0;
  border-bottom: 1px solid var(--border);
}
.mega-wrap > button {
  display: flex;
  align-items: center;
  gap: 6px;
  background: none;
  border: 0;
}
.mega-panel {
  position: absolute;
  top: 80%;
  right: 0;
  width: min(640px, 95cqi);
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  padding: 28px;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 20px 50px #00000015;
}
.mega-panel span {
  display: block;
  font-size: 0.8125rem;
  color: var(--muted-foreground);
  margin-top: 6px;
}
.hero {
  padding: calc(88px * var(--density)) 0;
  min-height: 600px;
  position: relative;
  display: grid;
  align-items: center;
  gap: 60px;
}
.hero h1 {
  font-size: calc(clamp(2.3rem, 5cqi, 4.5rem) * var(--heading-scale));
  max-width: 900px;
  line-height: 1.03;
  letter-spacing: -0.06em;
}
.hero-copy > p {
  max-width: 540px;
  font-size: 1.125rem;
  margin-top: 24px;
  line-height: 1.7;
}
.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  align-items: center;
  margin-top: 32px;
}
.hero-split,
.hero-terminal,
.hero-product,
.hero-profile {
  grid-template-columns: 1fr 1fr;
}
.hero-centered {
  display: flex;
  flex-direction: column;
  text-align: center;
  gap: 32px;
}
.hero-centered .hero-copy > p,
.hero-centered h1 {
  margin-left: auto;
  margin-right: auto;
}
.hero-centered .hero-actions {
  justify-content: center;
}
.hero-centered .sample-visual {
  width: min(880px, 100%);
  margin-top: 24px;
}
.hero-proof {
  display: flex;
  gap: 16px;
  align-items: center;
  font-size: 0.8125rem;
  color: var(--muted-foreground);
}
.hero-photo {
  background-size: cover;
  background-position: center;
  min-height: 460px;
  border-radius: var(--radius);
}
.hero-editorial {
  grid-template-columns: 1.15fr 1fr;
  gap: 32px;
  padding-top: 40px;
}
.edition-label {
  grid-column: 1/-1;
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  border-bottom: 1px solid var(--border);
  padding-bottom: 18px;
}
.editorial-caption {
  grid-column: 2;
  font-size: 0.75rem;
}
.hero-statement {
  min-height: 640px;
  gap: 30px;
  padding-top: 40px;
}
.hero-statement h1 {
  font-size: calc(clamp(3rem, 8cqi, 7.8rem) * var(--heading-scale));
  max-width: 1100px;
}
.display-index {
  font-family: monospace;
  font-size: 1.3rem;
  color: var(--primary);
}
.statement-foot {
  display: flex;
  justify-content: space-between;
  border-top: 1px solid var(--border);
  padding-top: 24px;
  font-size: 0.8125rem;
}
.product-stage {
  padding: 28px;
  background: var(--accent);
  border-radius: calc(var(--radius) * 2);
  transform: rotate(-2deg);
}
.product-stage > .ui-badge {
  margin-bottom: 20px;
}
.product-caption {
  text-align: center;
  font-size: 0.8125rem;
  margin-top: 24px;
}
.hero-immersive,
.hero-video {
  min-height: 680px;
  width: 100% !important;
  max-width: none;
  padding: 80px max(48px, calc((100cqi - var(--content-width)) / 2)) !important;
  color: var(--media-foreground);
  background: var(--media-background);
}
.hero-immersive > .hero-photo,
.hero-video > .hero-photo {
  position: absolute;
  inset: 0;
  border-radius: 0;
  filter: brightness(0.45);
}
.hero-immersive .hero-copy,
.hero-video .hero-copy {
  position: relative;
  z-index: 1;
  max-width: 700px;
}
.hero-immersive p,
.hero-video p,
.hero-immersive .eyebrow,
.hero-video .eyebrow {
  color: var(--media-foreground);
}
.hero-immersive .text-link,
.hero-video .text-link {
  color: var(--media-foreground);
}
.immersive-caption {
  position: relative;
  font-size: 0.8125rem;
}
.hero-play {
  position: relative;
  justify-self: start;
}
.terminal-window {
  background: var(--sidebar);
  color: var(--sidebar-foreground);
  padding: 26px;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  box-shadow: 0 20px 50px #00000014;
}
.terminal-window > div {
  display: flex;
  gap: 10px;
  border-bottom: 1px solid var(--border);
  padding-bottom: 16px;
  font-size: 0.8125rem;
}
.terminal-window pre {
  font-size: 0.875rem;
  line-height: 2.3;
  margin: 24px 0;
}
.hero-mosaic {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 16px;
}
.hero-mosaic .hero-photo {
  grid-row: span 2;
  min-height: 460px;
}
.mosaic-note {
  background: var(--primary);
  color: var(--primary-foreground);
  padding: 32px;
  border-radius: var(--radius);
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.mosaic-note .eyebrow {
  color: inherit;
}
.mosaic-small {
  background-size: cover;
  background-position: center;
  min-height: 210px;
  border-radius: var(--radius);
}
.hero-mosaic .hero-copy {
  max-width: 900px;
}
.hero-search {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  min-height: 480px;
  gap: 24px;
}
.hero-search .hero-copy > p {
  margin-left: auto;
  margin-right: auto;
}
.hero-search .hero-actions {
  display: none;
}
.hero-search form {
  width: min(700px, 100%);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px 10px 20px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--card);
  box-shadow: 0 10px 35px #00000009;
}
.hero-search form input {
  border: 0;
}
.hero-search .search-suggestions {
  max-width: 700px;
}
.hero-profile .hero-photo {
  min-height: 540px;
  border-radius: 50% 50% var(--radius) var(--radius);
}
.profile-signature {
  grid-column: 2;
  font-family: Georgia, serif;
  font-style: italic;
  font-size: 1.4rem;
}
.profile-signature span {
  display: block;
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-style: normal;
  color: var(--muted-foreground);
}
.hero-countdown {
  grid-template-columns: 1.3fr 0.7fr;
  gap: 30px;
}
.hero-countdown > .ui-badge {
  justify-self: start;
  grid-column: 1/-1;
}
.hero-countdown > .signup-form {
  grid-column: 1/-1;
}
.event-date {
  border-left: 1px solid var(--border);
  padding-left: 40px;
  display: flex;
  flex-wrap: wrap;
  gap: 22px;
  align-items: center;
}
.event-date strong {
  font-size: 5rem;
  line-height: 1;
  letter-spacing: -0.08em;
}
.event-date > span {
  font-size: 0.875rem;
  font-weight: 600;
}
.sample-visual {
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) * 1.1);
  background: var(--card);
  overflow: hidden;
  box-shadow: 0 20px 50px #0000000c;
  min-width: 0;
}
.sample-top {
  padding: 15px 20px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.75rem;
}
.sample-top > span {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
}
.sample-body {
  display: grid;
  grid-template-columns: 48px 1fr;
}
.sample-body > aside {
  display: flex;
  align-items: center;
  flex-direction: column;
  gap: 24px;
  padding: 22px 0;
  background: var(--muted);
  color: var(--muted-foreground);
}
.sample-body > div {
  padding: 22px;
  min-width: 0;
}
.sample-body h3 {
  font-size: 1rem;
  margin-top: 7px;
}
.sample-body .muted {
  font-size: 0.6875rem;
}
.mini-metrics {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 24px;
}
.mini-metrics .ui-card {
  padding: 15px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  box-shadow: none;
}
.mini-metrics small {
  font-size: 0.6875rem;
  color: var(--muted-foreground);
}
.mini-metrics strong {
  font-size: 1.5rem;
}
.mini-bars {
  height: 125px;
  display: flex;
  gap: 7px;
  align-items: end;
  padding: 20px 0 0;
  border-bottom: 1px solid var(--border);
}
.mini-bars span {
  flex: 1;
  background: var(--primary);
  border-radius: 3px 3px 0 0;
  opacity: 0.8;
}
.mini-bars span:nth-child(2n) {
