}
.sample-task {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 0.65rem;
  margin-top: 20px;
}
.sample-task > .muted {
  margin-left: auto;
}
.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
