}
.feature-grid .ui-card {
  height: 100%;
}
.feature-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px;
  background: var(--accent);
  color: var(--primary);
  border-radius: calc(var(--radius) * 0.75);
