  font-weight: 700;
}
.feature-grid h3 {
  margin-bottom: 12px;
}
.features-bento .feature-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.features-bento .feature-grid > div:first-child {
  grid-column: span 2;
  grid-row: span 2;
}
.features-bento .sample-visual {
  margin-top: 28px;
}
.features-numbered .feature-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
.features-numbered .ui-card {
  border: 0;
