}
.alternating-items {
  display: flex;
  flex-direction: column;
  gap: 90px;
}
.alternating-items > div,
.feature-tab {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 70px;
}
.alternating-items > div:nth-child(even) > div:first-child {
