  font-weight: 650;
  letter-spacing: -0.06em;
  margin: 20px 0 12px;
}
.price small {
  font-size: 0.875rem;
  color: var(--muted-foreground);
  letter-spacing: 0;
  margin-left: 5px;
  font-weight: 400;
}
.pricing-grid ul {
  flex: 1;
}
.pricing-single .pricing-grid {
  max-width: 600px;
  margin: auto;
