  grid-template-columns: 1fr 2fr;
  gap: 40px;
}
.pricing-split .pricing-grid {
  grid-template-columns: 1fr;
}
.pricing-split .ui-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px 30px;
}
.pricing-split .ui-card ul {
  grid-column: 2;
  grid-row: 1 / span 4;
}
.pricing-split .price {
