  margin-bottom: 30px;
  max-width: 420px;
}
.comparison-table {
  margin-top: 30px;
  overflow: auto;
}
.comparison-table th {
  color: var(--foreground);
}
.comparison-table td {
  color: var(--muted-foreground);
}
.quote-grid {
