.testimonials-spotlight blockquote h3,
.testimonials-editorial blockquote h3 {
  font-size: 2.5rem;
}
.testimonials-spotlight .ui-card {
  text-align: center;
  padding: 60px;
}
.testimonials-editorial .ui-card {
  border: 0;
  border-left: 3px solid var(--primary);
  border-radius: 0;
  background: none;
  padding: 20px 40px;
}
.testimonials-editorial blockquote {
  font-family: Georgia, serif;
}
.testimonials-split {
  display: grid;
  grid-template-columns: 1fr 1.4fr;
  gap: 60px;
}
.testimonials-split .quote-grid {
  grid-template-columns: 1fr;
}
.testimonials-wall .quote-grid {
  grid-template-columns: 1fr 1.3fr 1fr;
