.ui-accordion [role="region"] {
  overflow: hidden;
}
.ui-accordion [role="region"][data-state="open"] {
  animation: accordion-down var(--motion-duration) ease-out;
}
.ui-accordion [role="region"][data-state="closed"] {
  animation: accordion-up var(--motion-duration) ease-out;
}
@keyframes accordion-down {
  from {
    height: 0;
    opacity: 0;
  }
  to {
    height: var(--radix-accordion-content-height);
    opacity: 1;
  }
}
@keyframes accordion-up {
  from {
    height: var(--radix-accordion-content-height);
    opacity: 1;
  }
  to {
    height: 0;
    opacity: 0;
  }
}

