  .documentation-code pre {
    font-size: 0.75rem;
    padding: 18px;
  }
}

/* Portals size themselves against the visible viewport, outside template containers. */
@media (max-width: 800px) {
  .ui-dialog {
    padding: 26px;
  }
}
@media (max-width: 480px) {
  .ui-toast {
    bottom: 12px;
    right: 12px;
    left: 12px;
    font-size: 0.8125rem;
  }
}
.factory-preview
  :is(.hero, .feature-grid, .item-grid, .dashboard-grid, .form-grid, .documentation-section)
  > * {
  min-width: 0;
}
.factory-preview :is(.footer-links, .spread) {
  flex-wrap: wrap;
}
.factory-preview .dashboard-content {
  max-width: var(--content-width);
}
.ui-input[aria-invalid="true"] {
  border-color: var(--destructive);
}
@media (pointer: coarse) {
  .button-sm {
    min-height: 44px;
  }
}

.mobile-studio {
  display: grid;
  gap: 24px;
  min-width: 0;
}
.mobile-studio h1 {
  font-size: clamp(26px, 4vw, 44px);
  letter-spacing: -0.04em;
}
.mobile-studio header p {
  margin-block: 12px;
}
.mobile-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: end;
  padding: 20px;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 16px;
}
.mobile-controls > label {
  display: grid;
  gap: 8px;
  max-width: 100%;
  font-size: 13px;
}
.mobile-controls select,
.mobile-controls button {
  min-height: 44px;
  padding: 8px 12px;
  border: 1px solid var(--border);
  background: var(--background);
  border-radius: 8px;
  max-width: 100%;
}
.mobile-controls pre {
  max-width: 100%;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.mobile-stage {
  display: flex;
  justify-content: center;
  padding-block: 24px;
  min-width: 0;
  background: repeating-linear-gradient(
    45deg,
    transparent,
    transparent 12px,
    var(--muted) 12px,
    var(--muted) 13px
  );
}
.mobile-preview {
  border: 1px solid var(--border);
  border-radius: 28px;
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-body);
  box-shadow: 0 20px 60px #00000012;
}
.mobile-flow {
  display: grid;
  gap: calc(16px * var(--density));
  padding: max(20px, env(safe-area-inset-top)) max(16px, env(safe-area-inset-right))
    max(24px, env(safe-area-inset-bottom)) max(16px, env(safe-area-inset-left));
  min-width: 0;
}
.mobile-flow h2 {
  font-family: var(--font-heading);
  font-weight: var(--heading-weight);
  font-size: clamp(23px, 7cqi, 36px);
  line-height: 1.15;
  letter-spacing: -0.035em;
}
.mobile-flow p {
  line-height: 1.6;
  font-size: 14px;
  margin: 0;
}
.mobile-flow > p:first-child {
  font-size: 11px;
  letter-spacing: 0.16em;
  font-weight: 700;
}
.mobile-card {
  display: grid;
  min-width: 0;
  gap: 12px;
  padding: calc(18px * var(--density));
  border: var(--border-width) var(--border-style) var(--border);
  background: var(--card);
  color: var(--card-foreground);
  border-radius: var(--radius);
  box-shadow: var(--elevation);
}
.mobile-art {
  display: grid;
  place-items: center;
  min-height: 150px;
  font-size: 90px;
  background: var(--gradient-hero);
  color: var(--primary);
  border-radius: var(--radius);
}
.mobile-field {
  display: grid;
  gap: 8px;
  font-size: 14px;
  min-width: 0;
}
.mobile-field input,
.mobile-field select {
  width: 100%;
  min-width: 0;
  min-height: 48px;
  padding: 10px 12px;
  font-size: 16px;
  color: var(--foreground);
  background: var(--background);
  border: 1px solid var(--input);
  border-radius: var(--radius);
}
.mobile-flow button {
  min-height: 44px;
  max-width: 100%;
  white-space: normal;
  height: auto;
  padding-block: 12px;
}
.mobile-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 48px;
}
.mobile-toggle input {
  width: 28px;
  height: 28px;
  accent-color: var(--primary);
}
.mobile-error {
  color: var(--destructive);
  border-inline-start: 3px solid;
  padding: 12px;
}
.mobile-status {
  color: var(--success);
  border-inline-start: 3px solid;
  padding: 12px;
}
.mobile-tabs {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  border-top: 1px solid var(--border);
  padding-top: 12px;
  gap: 2px;
}
.mobile-tabs button {
  font-size: 11px;
  padding: 8px 2px;
  border-radius: 8px;
}
.mobile-tabs button[aria-current] {
  background: var(--selected);
}
